training.problem:
Given the following Java code snippet that is intended to perform a Radix Sort on an array of integers, identify the errors and correct them. Additionally, explain the workings of the correct Radix sort algorithm.

```java
public class Main {
    public static void main(String[] args) {
        int[] arr = {170, 45, 75, 90, 802, 24, 2, 66};

        radixsort(arr);
        print(arr);
    }

    static void radixsort(int arr[]) {
        int m = getMax(arr);
        for (int exp = 1; m/exp > 0; exp *= 10)
            countSort(arr, m, exp);
    }

    static void countSort(int arr[], int n, int exp) {
        int output[] = new int[n];
        int count[] = new int[10];

        for (int i = 0; i < n; i++)
            count[(arr[i]/exp)%10]++;

        for (int i = 1; i < 10; i++)
            count[i] += count[i - 1];

        for (int i = n; i >= 0; i--) {
            output[count[(arr[i]/exp)%10] - 1] = arr[i];
            count[(arr[i]/exp)%10]--;
        }

        for (int i = 0; i < n; i++)
            arr[i] = output[i];
    }

    static int getMax(int arr[]) {
        int mx = arr[0];
        for (int i = 1; i < arr.length; i++)
            if (arr[i] > mx)
                mx = arr[i];
        return mx;
    }

    static void print(int arr[]) {
        for (int i=0; i<arr.length; i++)
            System.out.print(arr[i]+" ");
    }
}
