Question:
Modify the Lockable interface and Coin2 class to include a new method called resetKey that allows the key to be changed. The method should take two integer parameters: the current key and the new key.

Solution:
Modified Lockable.java

```java
package samplepro;

public interface Lockable {
    public void setKey(int key);
    public void lock(int key);
    public void unlock(int key);
    public boolean locked();
    public void resetKey(int currentKey, int newKey); // New method added
}
```

Modified Coin2.java

```java
package samplepro;

public class Coin2 implements Lockable {
    private final int HEADS = 0;
    private final int TAILS = 1;
    private final int LOCKED = 2;
    private int key = 0;
    private int face;

    public Coin2() {
        flip();
    }

    @Override
    public void setKey(int key) {
        this.key = key;
    }

    @Override
    public void lock(int key) {
        if (this.key == key)
            face = LOCKED;
    }

    @Override
    public void unlock(int key) {
        if (this.key == key)
            face = -1;
    }

    @Override
    public boolean locked() {
        if (face == LOCKED)
            return true;
        else return false;
    }

    @Override
    public void resetKey(int currentKey, int newKey) { // New method added
        if (this.key == currentKey) {
            this.key = newKey;
        }
    }

    public void flip() {
        if (face != LOCKED)
            face = (int) (Math.random() * 2);
    }

    public boolean isHeads() {
        return (face == HEADS);
    }

    public String toString() {
        String faceName;
        if (face == HEADS)
            faceName = "Heads";
        else if (face == TAILS)
            faceName = "Tails";
        else
            faceName = "LOCKED";
        return faceName;
    }
}
```

